mod ring;mod reference;
#[path="../root-action/prepare.rs"]mod prepare;
#[path="../multi/algebra.rs"]mod algebra;
use hec_native_ic::{counted,fp::Fp,jac::{Curve,Div},poly::Poly,rng::Rng,oracle::{split_reference,OracleStats}};
use ring::{R,ZERO,ONE,Ring,Dsu};
use std::{fs,io::Write};
fn roots(ell:u64)->Vec<u64>{let f=Fp::new(ell);assert_eq!((ell-1)%5,0);let w=(2..ell).map(|a|f.pow(a,(ell-1)/5)).find(|&w|w!=1).unwrap();let mut v=vec![];let mut x=1;for _ in 1..5{x=f.mul(x,w);v.push(x)}v.sort_unstable();v.dedup();assert_eq!(v.len(),4);v}
fn compare(s:&Dsu,refs:&[(u64,reference::Pair)]){for(x,r)in refs{assert_eq!(s.status(*x),r.status(),"component {x}");}assert_eq!(s.survivors(),refs.iter().filter(|x|x.1.status().is_some()).count());}
fn insert(s:&mut Dsu,refs:&mut[(u64,reference::Pair)],v:&[R],rhs:R){s.insert(v,rhs);for(x,r)in refs.iter_mut(){let w:Vec<_>=v.iter().map(|a|s.ring.eval(*a,*x)).collect();r.insert(&w,s.ring.eval(rhs,*x));}compare(s,refs)}
fn synthetic(){let ell=7481;let xs=roots(ell);let rr=Ring::new(ell);let a=rr.sub(rr.z(1),rr.constant(xs[0]));let mut s=Dsu::new(0,ell);let mut refs:Vec<_>=xs.iter().map(|&x|(x,reference::Pair::new(2,ell))).collect();let cases=[(vec![a,ZERO],ZERO,4),(vec![ZERO,ONE],rr.constant(5),4),(vec![ZERO,ZERO],a,1),(vec![ZERO,ZERO],ONE,0)];for(i,(v,rhs,n))in cases.into_iter().enumerate(){insert(&mut s,&mut refs,&v,rhs);assert_eq!(s.survivors(),n);if i==2{assert_eq!(s.unique(),Some((xs[0],Some(5))))}eprintln!("AUX label_step={i} survivors={n} passed=true");}let mut s=Dsu::new(0,ell);let mut refs:Vec<_>=xs.iter().map(|&x|(x,reference::Pair::new(2,ell))).collect();insert(&mut s,&mut refs,&[a,ZERO],ONE);assert_eq!(s.survivors(),3);eprintln!("AUX zero_pivot_inconsistent_only_one_root_rejected=true");let mut s=Dsu::new(2,ell);let mut refs:Vec<_>=xs.iter().map(|&x|(x,reference::Pair::new(4,ell))).collect();insert(&mut s,&mut refs,&[ONE,rr.neg(rr.z(1)),ZERO,ONE],ZERO);insert(&mut s,&mut refs,&[ONE,rr.neg(rr.z(2)),ZERO,ZERO],ONE);assert_eq!(s.lp_rank,2);assert_eq!(s.survivors(),4);eprintln!("AUX unbalanced_cycle_unit_grounding_all_components=true");}
fn weight(c:&Curve,map:&[(usize,usize,u64)],j:usize,y:u64,rr:&Ring)->R{let(_,e,basey)=map[j];let a=rr.z(e);if y==basey{a}else{assert_eq!(y,c.fp.neg(basey));rr.neg(a)}}
fn source_row(c:&Curve,d:&Div,fb:&[(u64,u64)],map:&[(usize,usize,u64)],cols:usize,rr:&Ring)->Option<Vec<R>>{let roots=split_reference(&d.u,&c.fp,&mut OracleStats::default())?;let mut v=vec![ZERO;cols+1];let mut sum=c.zero();for &(x,m)in roots.as_slice(){let j=fb.binary_search_by_key(&x,|p|p.0).unwrap();let y=d.v.eval(x,&c.fp);let r=if map[j].0==0{cols-1}else{map[j].0-1};v[r]=rr.add(v[r],rr.scale(weight(c,map,j,y,rr),m as u64));for _ in 0..m{sum=c.add_place(&sum,x,y)}}assert_eq!(sum,*d);Some(v)}
fn main(){counted::disable();synthetic();let root="research/hec_residual_span_20261116";let raw=fs::read_to_string(format!("{root}/incidence-oracle/ROOTS.tsv")).unwrap();let mut prefix=fs::File::create_new(format!("{root}/cyclotomic-lp/PREFIX.tsv")).unwrap();writeln!(prefix,"p\tsm\trow\tsurvivors\tlp_rank\tunique_lambda\tk").unwrap();println!("p\tsm\trows\tfirst_unique_row\tfirst_unique_k_row\tfinal_lambda\tk\tsurvivors");let mut checked=0;
for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let(fb,z)=prepare::prepare(&c);let rr=Ring::new(ell);let mut map=vec![(usize::MAX,0,0);fb.len()];let mut cols=0;for j in 0..fb.len(){if map[j].0!=usize::MAX{continue}let(mut x,y)=(fb[j].0,fb[j].1);for e in 0..5{let k=fb.binary_search_by_key(&x,|p|p.0).unwrap();assert_eq!(map[k].0,usize::MAX);map[k]=(cols,e,y);x=c.fp.mul(x,z);}cols+=1;}let base=c.place(fb[0].0,fb[0].1);let mut rng=Rng::new(2026112500^p);
for sm in [1,17]{let d=c.mul(&base,sm);let qualification=1+rng.below(ell-1);let target=c.mul(&d,qualification);let mut s=Dsu::new(cols-1,ell);let mut refs:Vec<_>=roots(ell).into_iter().map(|x|(x,reference::Pair::new(cols+1,ell))).collect();if let Some(v)=source_row(&c,&d,&fb,&map,cols,&rr){insert(&mut s,&mut refs,&v,ONE);}let(mut index,mut first,mut first_k)=(0,None,None);for line in raw.lines().skip(1){let v:Vec<_>=line.split('\t').collect();if v[0].parse::<u64>().unwrap()!=p||v[1].parse::<u64>().unwrap()!=sm{continue}let support:Vec<Vec<u64>>=v[5].split(',').map(|x|x.split(':').map(|v|v.parse().unwrap()).collect()).collect();if !support.iter().any(|x|x[0]==0){continue}index+=1;let mut coeff=vec![ZERO;cols+1];for x in support{let j=fb.binary_search_by_key(&x[1],|p|p.0).unwrap();assert_eq!(map[j].0,x[0]as usize);let r=if map[j].0==0{cols-1}else{map[j].0-1};coeff[r]=rr.add(coeff[r],weight(&c,&map,j,x[2],&rr));}coeff[cols]=ONE;let a=v[3].parse::<u64>().unwrap();insert(&mut s,&mut refs,&coeff,rr.constant((ell-a%ell)%ell));checked+=1;assert!(s.survivors()>0);let unique=s.unique();if unique.is_some()&&first.is_none(){first=Some(index)}if unique.is_some_and(|x|x.1.is_some())&&first_k.is_none(){first_k=Some(index)}writeln!(prefix,"{p}\t{sm}\t{index}\t{}\t{}\t{}\t{}",s.survivors(),s.lp_rank,unique.map_or("none".into(),|x|x.0.to_string()),unique.and_then(|x|x.1).map_or("none".into(),|x|x.to_string())).unwrap();}
let(lambda,k)=s.unique().expect("retained panel unique");let k=k.expect("retained panel target");assert_eq!(algebra::action(&c,&d,z),c.mul(&d,lambda));assert_eq!(c.mul(&d,k),target);println!("{p}\t{sm}\t{index}\t{}\t{}\t{lambda}\t{k}\t{}",first.unwrap(),first_k.unwrap(),s.survivors());}}
eprintln!("streams=6 ring_row_prefixes={checked} all_four_components_match_sparse_and_reverse_dense=true synthetic_zero_divisors_and_grounding_pass=true all_original_action_target_checks=true no_character_input_to_ring=true no_cost_claim=true");}
